/*
This structure contains the master iteration data that we want want to log
    - num_iter : number of master iteration
    - PTDF_compute_time : elapsed time to compute the new PTDF
    - removing_rows_per_sub_time : elapsed time to remove the constraints added to subproblem
workers
*/

/*
This map will be used will be attached to each master iteration.
we map each subproblem into the different micoiteration during a benders iteration
*/
// using MicroIterationsPerSub = std::map<std::string, std::vector<MicroIterationLog>>;

class MicroIterationsLog
{
public:
    /*

        Constructor
        @input :
            - options : configuration of the study
            - sub_constraints_map : mapping sub to constraints
            - constraints_per_line : mapping constraint keys to the list of constraints to add
            - warm_start : handle warm_start mechanism
            - world : the mpi communicator
            - log_level : log level necessary to determine if we dump the added keys at each micro
       iteration if >= 3

    */
    MicroIterationsLog(const std::filesystem::path& output_root,
                       bool warm_start,
                       mpi::communicator* world,
                       int log_level);

    /*
        Called in the benders master resolution end callback.
        It will set the number of iteration, the master resolution time and the time to compute
        the new PTDF.
        @input
            - num_iter : number of master iteration
            - master_resolution_time : elapsed time of the master resolution (ms)
            - elapsed_time : elapsed time of computing PTDF
    */
    void AddMasterIterationLog(int num_iter,
                               double master_resolution_time,
                               std::string elapsed_time = "");

    /*
        Called in the micro iteration end callback.
        It will set the output data we want to dump for micro iterations for each subproblem and
        at each master iteration.
        @inputs :
            - sub_name : subproblem name
            - solving_name : time to solve subproblem
            - adding_rows_time : elapsed time to add constraints
            - added_constraints_keys : keys of added constraints
    */
    void AddMicroIterionLog(std::string sub_name,
                            int num_micro_iter,
                            int num_master_iter,
                            std::string solving_time,
                            std::vector<std::string> added_constraints_keys,
                            std::string elapsed_time);

    void AddMicroIterCount(std::string sub_name, int num_micro_iter);

    void DumpAddedConstraints(int num_micro_iter,
                              int num_master_iter,
                              std::string sub_name,
                              const std::vector<std::string>& constraints_to_add,
                              const std::vector<bool>& constraints_to_add_is_N,
                              size_t start,
                              size_t end);

    ~MicroIterationsLog();

    // non-copyable, non-movable (owns a thread)
    MicroIterationsLog(const MicroIterationsLog&) = delete;
    MicroIterationsLog& operator=(const MicroIterationsLog&) = delete;

private:
    void enqueue(std::function<void()> task);
    void workerLoop();
    void enqueueHttp(std::string path, std::string body);
    void httpWorkerLoop();

    std::filesystem::path output_root_ ;
    mpi::communicator* _world;
    bool warm_start_;
    std::map<std::string, std::string> sub_constraints_map_;
    std::ofstream log_file_;
    int log_level_;

    // async logging
    std::thread worker_thread_;
    std::mutex queue_mutex_;
    std::condition_variable queue_cv_;
    std::queue<std::function<void()>> task_queue_;
    bool stop_ = false;

    // async http sending (POST /micro_iter, /master_times and /added_constraints on localhost:3123), own thread so a
    // slow or absent server never delays file logging. Queue items are {path, body}.
    MicroIterationsHttpSender http_sender_{"127.0.0.1", 3123};
    std::thread http_thread_;
    std::mutex http_mutex_;
    std::condition_variable http_cv_;
    std::queue<std::pair<std::string, std::string>> http_queue_;
    bool http_stop_ = false;
};

#include <fstream>
#include <sstream>
#include "micro_iterations_logger.h"

MicroIterationsLog::MicroIterationsLog(
  const std::filesystem::path& output_root,
  bool warm_start,
  mpi::communicator* world,
  int log_level)
{
    warm_start_ = warm_start;
    _world = world;
    log_level_ = log_level;
    output_root_ = output_root;

    std::filesystem::path micro_iterations_log_path = std::filesystem::path(output_root_)
                                                      / std::filesystem::path(
                                                        "micro_iterations_proc_"
                                                        + std::to_string(world->rank()) + ".log");

    log_file_.open(micro_iterations_log_path.c_str());

    log_file_ << "************************** MICRO ITERS config ************************** \n\n";
    if (warm_start_)
    {
        log_file_ << "warm_start=1\n\n";
    }
    else
    {
        log_file_ << "warm_start=0\n\n";
    }

    if (world->rank() == 0)
    {
        std::filesystem::path added_constraints_repo_path = std::filesystem::path(
                                                              output_root_)
                                                            / "added_constraints";
        if (!std::filesystem::exists(added_constraints_repo_path))
        {
            std::filesystem::create_directories(added_constraints_repo_path);
        }
        else
        {
            std::filesystem::remove_all(added_constraints_repo_path);
            std::filesystem::create_directories(added_constraints_repo_path);
        }
    }

    // Start the background worker thread
    worker_thread_ = std::thread(&MicroIterationsLog::workerLoop, this);
    // HTTP: second background thread, drains http_queue_ and POSTs to the frontend server
    // (disabled for now)
    // http_thread_ = std::thread(&MicroIterationsLog::httpWorkerLoop, this);
}

MicroIterationsLog::~MicroIterationsLog()
{
    {
        std::lock_guard<std::mutex> lock(queue_mutex_);
        stop_ = true;
    }
    queue_cv_.notify_one();
    if (worker_thread_.joinable()) {
        worker_thread_.join();
    }

    // HTTP: stop the sender thread; it drains the remaining queued requests before exiting
    {
        std::lock_guard<std::mutex> lock(http_mutex_);
        http_stop_ = true;
    }
    http_cv_.notify_one();
    if (http_thread_.joinable()) {
        http_thread_.join();
    }
}

void MicroIterationsLog::enqueue(std::function<void()> task)
{
    {
        std::lock_guard<std::mutex> lock(queue_mutex_);
        task_queue_.push(std::move(task));
    }
    queue_cv_.notify_one();
}

void MicroIterationsLog::workerLoop()
{
    while (true) {
        std::function<void()> task;
        {
            std::unique_lock<std::mutex> lock(queue_mutex_);
            queue_cv_.wait(lock, [this] { return stop_ || !task_queue_.empty(); });

            if (stop_ && task_queue_.empty()) {
                break;
            }

            task = std::move(task_queue_.front());
            task_queue_.pop();
        }
        task();
    }
}

// HTTP: push a {path, json body} request on http_queue_ (non-blocking for the solver thread)
void MicroIterationsLog::enqueueHttp(std::string path, std::string body)
{
    {
        std::lock_guard<std::mutex> lock(http_mutex_);
        http_queue_.emplace(std::move(path), std::move(body));
    }
    http_cv_.notify_one();
}

// HTTP: sender thread body. Pops requests one by one and sends them via MicroIterationsHttpSender
void MicroIterationsLog::httpWorkerLoop()
{
    while (true) {
        std::pair<std::string, std::string> request;
        {
            std::unique_lock<std::mutex> lock(http_mutex_);
            http_cv_.wait(lock, [this] { return http_stop_ || !http_queue_.empty(); });

            if (http_stop_ && http_queue_.empty()) {
                break;
            }

            request = std::move(http_queue_.front());
            http_queue_.pop();
        }
        // HTTP: POST the JSON body (request.second) to the frontend server at the path
        // request.first (e.g. "/master_times"). Send() opens a fresh connection per request and
        // closes it afterwards. The returned bool is ignored on purpose: failures are reported on
        // stderr by the sender; never block or abort the solver
        http_sender_.Send(request.first, request.second);
    }
}

