- `cpp_plugin/micro_iters_cpp_plugin.cpp` (lines 1-300): the entire target file; every function and callback was read in full.
- `cpp_plugin/gridModelisation.h` (lines 660-699, 446, 508): only to confirm the signatures/return contract of `return_constraints_for_micro_iteration`, `compute_factors_for_micro_iterations`, and `broadcast_factors` used at the boundary.
- `utils/micro_iterations_logger.h` (lines 60-110): only to confirm the logger method signatures called from the callbacks.
- `README.md` (lines 1-120): for the callback lifecycle description and confirmation of the dictionary file names.

#pragma once

#include <string>

// Minimal HTTP client (raw POSIX sockets) posting a JSON body to http://host:port/<path>,
// the path being given per request.
// One connection per request, same approach as IterationDataHttpSender in antares-xpansion.
class MicroIterationsHttpSender
{
public:
    MicroIterationsHttpSender(std::string host, int port);
    ~MicroIterationsHttpSender();

    MicroIterationsHttpSender(const MicroIterationsHttpSender&) = delete;
    MicroIterationsHttpSender& operator=(const MicroIterationsHttpSender&) = delete;

    bool Send(const std::string& path, const std::string& json_body);

private:
    bool Connect();
    void Disconnect();

    std::string host_;
    int port_;
    int socket_fd_ = -1;
};

#include "micro_iterations_http_sender.h"

#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <unistd.h>

#include <cerrno>
#include <cstring>
#include <iostream>
#include <sstream>

MicroIterationsHttpSender::MicroIterationsHttpSender(std::string host, int port)
    : host_(std::move(host)), port_(port)
{
}

MicroIterationsHttpSender::~MicroIterationsHttpSender()
{
    // make sure no socket is left open when the sender is destroyed
    Disconnect();
}

bool MicroIterationsHttpSender::Connect()
{
    socket_fd_ = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd_ < 0)
    {
        std::cerr << "[MicroIterationsHttpSender] socket() failed: " << strerror(errno) << "\n";
        return false;
    }

    sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port_);
    if (inet_pton(AF_INET, host_.c_str(), &addr.sin_addr) <= 0)
    {
        std::cerr << "[MicroIterationsHttpSender] invalid address: " << host_ << "\n";
        // release the socket created above so it does not leak
        Disconnect();
        return false;
    }

    if (connect(socket_fd_, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) < 0)
    {
        std::cerr << "[MicroIterationsHttpSender] connect() failed: " << strerror(errno) << "\n";
        // release the socket created above so it does not leak
        Disconnect();
        return false;
    }

    return true;
}

void MicroIterationsHttpSender::Disconnect()
{
    if (socket_fd_ >= 0)
    {
        close(socket_fd_);
        socket_fd_ = -1;
    }
}

bool MicroIterationsHttpSender::Send(const std::string& path, const std::string& json_body)
{
    // open a new TCP connection to host_:port_ (one connection per request, see "Connection: close")
    if (!Connect())
    {
        return false;
    }

    std::ostringstream http;
    http << "POST " << path << " HTTP/1.1\r\n"
         << "Host: " << host_ << ":" << port_ << "\r\n"
         << "Content-Type: application/json\r\n"
         << "Content-Length: " << json_body.size() << "\r\n"
         << "Connection: close\r\n"
         << "\r\n"
         << json_body;
    std::string request = http.str();

    ssize_t sent = send(socket_fd_, request.c_str(), request.size(), MSG_NOSIGNAL);
    // close the socket right after sending, whether or not send() succeeded (no response is read)
    Disconnect();

    if (sent < 0)
    {
        std::cerr << "[MicroIterationsHttpSender] send() failed: " << strerror(errno) << "\n";
        return false;
    }

    return true;
}

