    EXPECT_NE(content.find("area1.mps ; 3"), std::string::npos);
}

TEST_F(MicroIterationsLogTest, DumpAddedConstraintsCreatesFile)
{
    {
        MicroIterationsLog logger(tmp_dir, false, g_world, 0);
        std::vector<std::string> constraints = {"constraint_A", "constraint_B", "constraint_C"};
        std::vector<bool> is_N = {true, false, true};
        logger.DumpAddedConstraints(0, 1, "path/to/area1.mps", constraints, is_N, 0, constraints.size());
    }

    if (g_world->rank() == 0)
    {
        fs::path expected_file = tmp_dir / "added_constraints"
                                         / "master_1" / "area1"
                                         / "micro_iter_0.txt";
        ASSERT_TRUE(fs::exists(expected_file)) << "Constraint file not created: " << expected_file;

        std::ifstream in(expected_file);
        std::string content((std::istreambuf_iterator<char>(in)),
                             std::istreambuf_iterator<char>());

        // All constraints are written: 1 for N, 0 for N_K
        EXPECT_NE(content.find("constraint_A 1"), std::string::npos);
        EXPECT_NE(content.find("constraint_B 0"), std::string::npos);
        EXPECT_NE(content.find("constraint_C 1"), std::string::npos);
    }
}

TEST_F(MicroIterationsLogTest, DumpAddedConstraintsMultipleMicroIterations)
{
    {
        MicroIterationsLog logger(tmp_dir, false, g_world, 0);
        logger.DumpAddedConstraints(0, 1, "sub1.mps", {"c1", "c2"}, {true, true}, 0, 2);
        logger.DumpAddedConstraints(1, 1, "sub1.mps", {"c3"}, {true}, 0, 1);
        logger.DumpAddedConstraints(0, 2, "sub1.mps", {"c4", "c5"}, {true, true}, 0, 2);
    }

    if (g_world->rank() == 0)
    {
        EXPECT_TRUE(fs::exists(tmp_dir / "added_constraints" / "master_1" / "sub1" / "micro_iter_0.txt"));
        EXPECT_TRUE(fs::exists(tmp_dir / "added_constraints" / "master_1" / "sub1" / "micro_iter_1.txt"));
        EXPECT_TRUE(fs::exists(tmp_dir / "added_constraints" / "master_2" / "sub1" / "micro_iter_0.txt"));

        // Verify content of the second file
        std::ifstream in(tmp_dir / "added_constraints" / "master_1" / "sub1" / "micro_iter_1.txt");
        std::string content((std::istreambuf_iterator<char>(in)),
                             std::istreambuf_iterator<char>());
        EXPECT_NE(content.find("c3"), std::string::npos);
        EXPECT_EQ(content.find("c1"), std::string::npos); // c1 should NOT be in this file
    }
}

int main(int argc, char** argv)
{
